// cursor pagination
{
  const rows = [
    { id: 'c', tenant: 'a', createdAt: '2026-01-01', total: 1 },
    { id: 'a', tenant: 'a', createdAt: '2026-01-01', total: 1 },
    { id: 'b', tenant: 'a', createdAt: '2026-01-01', total: 1 },
    { id: 'z', tenant: 'o', createdAt: '2026-01-01', total: 1 },
    { id: 'd', tenant: 'a', createdAt: '2026-01-02', total: 1 }
  ];
  const snapshot = JSON.stringify(rows);
  const h = new OrderHandler(new OrderRepository(rows));
  const p1 = h.list({ tenant: 'a', limit: 2 });
  assert.deepEqual(p1.items.map(x => x.id), ['a', 'b']);
  assert.equal(p1.nextCursor, '2026-01-01|b');
  const p2 = h.list({ tenant: 'a', limit: 2, cursor: p1.nextCursor });
  assert.deepEqual(p2.items.map(x => x.id), ['c', 'd']);
  assert.equal(p2.nextCursor, null);
  // deleted / other-tenant cursor pair
  assert.deepEqual(h.list({ tenant: 'a', limit: 5, cursor: '2026-01-01|bb' }).items.map(x => x.id), ['c', 'd']);
  assert.deepEqual(h.list({ tenant: 'a', limit: 5, cursor: '2026-01-01|z' }).items.map(x => x.id), ['d']);
  assert.equal(h.list({ tenant: 'a', limit: 5, cursor: '2026-01-02|d' }).nextCursor, null);
  for (const cursor of ['', 'x', '|', 'a|', '|a', 'a|b|c'])
    assert.throws(() => h.list({ tenant: 'a', limit: 1, cursor }), /invalid request/);
  for (const limit of [0, 101, 1.5, NaN])
    assert.throws(() => h.list({ tenant: 'a', limit }), /invalid request/);
  assert.throws(() => h.list({ tenant: '', limit: 1 }), /invalid request/);
  assert.equal(JSON.stringify(rows), snapshot);
}
